cat /app/resources/treasury_bulletin_1990_06.json | python3 -c "
import json, sys
d = json.load(sys.stdin)

# Search for tables with ESF data or monthly data
for i, elem in enumerate(d['document']['elements']):
    if elem.get('type') == 'table':
        content = elem.get('content', '')
        # Look for 'ESF' or tables with Oct/Nov 1989
        if 'ESF' in content or ('1989' in content and 'Oct.' in content):
            # Check if this looks like Exchange Stabilization Fund data
            if 'dollar' in content.lower() or 'thousand' in content.lower():
                if 'Polish' in content or 'zloty' in content or 'mark' in content:
                    print(f'Index {i}:')
                    print(content[:2500])
                    print('---')
"
